  if (!h) return null;
  const r = vpRect();
  const X = e.clientX - r.left, Y = e.clientY - r.top;
  const near = (p, rad = 10) => Math.hypot(p[0] - X, p[1] - Y) <= rad;
  if (e.altKey && near(h.pv, 14)) return 'pivot';
  if (near(h.rot)) return 'rot';
  for (let i = 0; i < 4; i++) if (near(h.corners[i])) return 'c' + i;
