    type: 'xf', mode: hit || 'move', layer, cel, x, before,
    d0: toDoc(e), x0: x.x, y0: x.y, rot0: x.rot, sx0: x.sx, sy0: x.sy,
    pv: h ? h.pv : [0, 0],
    a0: h ? Math.atan2(sy0 - h.pv[1], sx0 - h.pv[0]) : 0,
    r0: h ? Math.hypot(sx0 - h.pv[0], sy0 - h.pv[1]) || 1 : 1,
