  const x = nameW() + state.frame * CELL_W + CELL_W / 2 - 1;
  playheadEl.style.left = x + 'px';
  const vis = tlScroll.clientWidth - nameW();
  const rel = state.frame * CELL_W - tlScroll.scrollLeft;
