  cv.width = w; cv.height = h; cv.style.width = w + 'px';
  const g = cv.getContext('2d'); g.fillStyle = '#2a2a2a'; g.fillRect(0, 0, w, h);
  g.fillStyle = '#9aa7b5'; g.font = '11px sans-serif'; g.fillText('♪ ' + aud.name, 6, 21);
