  let re = 0, im = 0;
  for (let i = 0; i < n; i++) {
    const ax = pins[i][0] - px, ay = pins[i][1] - py, bx = cur[i][0] - qx, by = cur[i][1] - qy;
    re += w[i] * (bx * ax + by * ay); im += w[i] * (by * ax - bx * ay);
  }
