  const k0 = [...l.cels.keys()].sort((a, b) => a - b)[0], cel = l.cels.get(k0), bb = cel && celBBox(cel);
  const cx = bb ? bb.x + bb.w / 2 : px, cy = bb ? bb.y + bb.h / 2 : py + 60;
  const len = Math.max(20, Math.hypot(cx - px, cy - py)), rest = Math.atan2(cy - py, cx - px);
