  l.locked = true; l.opacity = opt.opacity;
  l.vref = { el: null, url: '', name: file.name, file: null, offset: opt.start, dur: 0, canvas: makeCanvas(state.w, state.h), fit: opt.fit || 'contain' };
  await vrefAttach(l, file);
