  if (ruler.ell && ruler.snap.ell) { const p = projEll(ruler.ell, d.x, d.y), dl = Math.hypot(p.x - d.x, p.y - d.y); if (dl < R) cand.push([dl, { type: 'ell', r: ruler.ell }]); }
