    for (let i = 0; i < 48; i++) { const a = i * Math.PI / 24; line(P.x - Math.cos(a) * 20000, P.y - Math.sin(a) * 20000, P.x + Math.cos(a) * 20000, P.y + Math.sin(a) * 20000, col); }
    handle(P.x, P.y, '#ffbe3c');
