    const t = ((B.mx - A.mx) * B.dy - (B.my - A.my) * B.dx) / den, P = [A.mx + A.dx * t, A.my + A.dy * t];
    if (Math.hypot(P[0] - V[k][0], P[1] - V[k][1]) > 0.25 * Math.hypot(...[0, 1].map(j => V[(k + 1) % n][j] - V[k][j]))) return V; // something odd: keep the simple corners
