  const k = 1.7 / Math.max(size.x, size.y, size.z);
  const wrap = new T.Group(), inner = new T.Group(); inner.add(obj); obj.position.sub(ctr); inner.scale.setScalar(k); inner.position.y = size.y * k / 2; wrap.add(inner);
  const parts = [];
