    if ((e.buttons & 32) || e.button === 5) {
      if (!penCfg.eraserPrev && !stroke && !active) { penCfg.eraserPrev = state.tool; const g = groupTool.eraser || 'eraser'; if (TOOLDEF[g]) selectTool(g); }
    }
